example.code:
use strict;
use warnings;
use feature "say";
say "Hello, Asha!";

use strict;
use warnings;
use feature "say";
my $pencils = 3;
say $pencils + 2;

use strict;
use warnings;
use feature "say";
my $name = "Ravi";
say "Hi, $name!";

use strict;
use warnings;
use feature "say";
my @pets = ("cat", "dog");
say $pets[1];

use strict;
use warnings;
use feature "say";
my %book = (title => "Moon Trip", pages => 24);
say $book{title};

use strict;
use warnings;
use feature "say";
my $score = 8;
if ($score >= 5) { say "Pass"; } else { say "Try again"; }

use strict;
use warnings;
use feature "say";
my $pet = "cat";
say $pet eq "cat" ? "Yes" : "No";

use strict;
use warnings;
use feature "say";
for my $n (1..3) { say $n; }

use strict;
use warnings;
use feature "say";
sub twice { my ($n) = @_; return $n * 2; }
say twice(4);

use strict;
use warnings;
use feature "say";
my $word = "cat";
say $word =~ /^c/ ? "Starts with c" : "Other";

use strict;
use warnings;
use feature "say";
my $text = "red red";
$text =~ s/red/blue/g;
say $text;

use strict;
use warnings;
use feature "say";
my @words = split /,/, "cat,dog";
say join " + ", @words;
